CREATE TABLE rating_batches (batch_id TEXT PRIMARY KEY, state TEXT NOT NULL CHECK(state IN ('DRAFT','OPEN','CLOSED')), seed INTEGER NOT NULL, criteria_version TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES accounts(actor_id), created_at TEXT NOT NULL, closed_at TEXT);
CREATE TABLE rating_assignments (assignment_id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES rating_batches(batch_id), response_id TEXT NOT NULL REFERENCES responses(response_id), blind_token TEXT NOT NULL UNIQUE, ordinal INTEGER NOT NULL, rater_id_hash TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('OPEN','SUBMITTED','VOID')), created_at TEXT NOT NULL, UNIQUE(batch_id,ordinal));
CREATE TABLE research_ratings (rating_id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL UNIQUE REFERENCES rating_assignments(assignment_id), criteria_json TEXT NOT NULL, band_half_step REAL, unrateable_reason TEXT, rationale TEXT NOT NULL, submitted_at TEXT NOT NULL);
CREATE TRIGGER research_ratings_immutable_update BEFORE UPDATE ON research_ratings BEGIN SELECT RAISE(ABORT,'research ratings are immutable'); END;
CREATE TRIGGER research_ratings_immutable_delete BEFORE DELETE ON research_ratings BEGIN SELECT RAISE(ABORT,'research ratings are immutable'); END;
CREATE TABLE adjudications (adjudication_id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL UNIQUE REFERENCES rating_assignments(assignment_id), adjudicator_id TEXT NOT NULL REFERENCES accounts(actor_id), criteria_json TEXT NOT NULL, band_half_step REAL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE machine_seen (response_id TEXT NOT NULL REFERENCES responses(response_id), actor_id TEXT NOT NULL REFERENCES accounts(actor_id), seen_at TEXT NOT NULL, source TEXT NOT NULL, PRIMARY KEY(response_id,actor_id));
CREATE TABLE feedback_studies (study_id TEXT PRIMARY KEY, title TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('DRAFT','RUNNING','SURVEY','CLOSED')), seed INTEGER NOT NULL, config_json TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES accounts(actor_id), created_at TEXT NOT NULL, closed_at TEXT);
CREATE TABLE study_enrollments (enrollment_id TEXT PRIMARY KEY, study_id TEXT NOT NULL REFERENCES feedback_studies(study_id), participant_id TEXT NOT NULL REFERENCES accounts(actor_id), pseudonym TEXT NOT NULL, arm TEXT NOT NULL, enrolled_at TEXT NOT NULL, withdrawn_at TEXT, UNIQUE(study_id,participant_id), UNIQUE(study_id,pseudonym));
CREATE TABLE study_surveys (survey_id TEXT PRIMARY KEY, enrollment_id TEXT NOT NULL REFERENCES study_enrollments(enrollment_id), phase TEXT NOT NULL CHECK(phase IN ('pre','post')), answers_json TEXT NOT NULL, submitted_at TEXT NOT NULL, UNIQUE(enrollment_id,phase));
CREATE TABLE review_sessions (session_id TEXT PRIMARY KEY, response_id TEXT NOT NULL REFERENCES responses(response_id), reviewer_id TEXT NOT NULL REFERENCES accounts(actor_id), started_at TEXT NOT NULL, ended_at TEXT, action TEXT, state TEXT NOT NULL);
CREATE TABLE sem_configs (config_id TEXT PRIMARY KEY, value REAL NOT NULL CHECK(value>0), method TEXT NOT NULL CHECK(method IN ('retest','manual')), source TEXT NOT NULL, sample_count INTEGER NOT NULL CHECK(sample_count>=0), created_by TEXT NOT NULL REFERENCES accounts(actor_id), created_at TEXT NOT NULL);
